import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Nguyen 2022 - Fig. 4'
sim.info.description = 'Binary CO2/He breakthrough experiment with CALF-20. Results correspond Fig 4 from the publication. The example is initialised with an inlet CO2 mole fraction of 0.7. Varying this value will correspond to the other cases in the paper. Experimental data from the publication is included in the example under the Data Plotter window.'
sim.info.author = 'Sam Affleck'

# ---- fluid --------------------------------------------------------------------
sim.add_component('CarbonDioxide')
sim.add_component('Nitrogen')
sim.add_component('Helium')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['CarbonDioxide'] = 37.435
sim.fluid.adsorbed_heat_capacity['Nitrogen'] = 29.171
sim.fluid.adsorbed_heat_capacity['Helium'] = 0.0

# ---- adsorbents -----------------------------------------------------------------
ads_calf_20 = sim.add_adsorbent('CALF-20', solid_density=570.0, heat_capacity=1371.0, thermal_conductivity=0.63, particle_void_fraction=0.35)
ads_calf_20.set_isotherm('extended_dual_site_langmuir_c', {
    'CarbonDioxide': {'m1': 2.387, 'b1': 5.519e-07, 'q1': 35060.0, 'm2': 3.271, 'b2': 5.187e-08, 'q2': 28950.0},
    'Nitrogen': {'m1': 2.387, 'b1': 8.139e-07, 'q1': 17960.0, 'm2': 3.271, 'b2': 8.139e-07, 'q2': 17960.0},
}, components=['CarbonDioxide', 'Nitrogen'])
ads_calf_20.set_isotherm('inert', components=['Helium'])
ads_calf_20.set_rate_model('CarbonDioxide', 'ldf', 'macropore', tortuosity=3.0, macropore_void_fraction=0.35)
ads_calf_20.set_rate_model('Nitrogen', 'ldf', 'macropore', tortuosity=3.0, macropore_void_fraction=0.35)
ads_calf_20.set_rate_model('Helium', 'ldf', 'constant', k=0.5)
ads_calf_20.heat_of_adsorption['CarbonDioxide'] = 38000.0
ads_calf_20.heat_of_adsorption['Nitrogen'] = 15000.0
ads_calf_20.heat_of_adsorption['Helium'] = 0.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.0282)
sim.bed.ambient_temperature = 295.0
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=7800.0, heat_capacity=502.0, thermal_conductivity=16.0)
sim.wall.thickness = 0.0018000000000000013
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_calf_20 = sim.add_layer('CALF-20', composition={'CALF-20': 1.0}, momentum='kozeny_carman', length=0.07818118829358225, cells=30, bed_void_fraction=0.4, particle_diameter=0.0015)
layer_calf_20.set_dispersion('ruthven', molecular_diffusion_coefficient=1.6e-05)
layer_calf_20.set_heat_dispersion('constant', heat_dispersion_coefficient=0.4)
layer_calf_20.set_internal_heat_transfer('constant', internal_htc=6.963)
layer_calf_20.set_external_heat_transfer('constant', external_htc=14.0)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 97000.0
sim.initial_conditions.temperature = 295.0
sim.initial_conditions.wall_temperature = 295.0
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Helium'] = 1.0
sim.initial_conditions.y['Nitrogen'] = 0.0
sim.initial_conditions.y['CarbonDioxide'] = 0.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 1
sim.cycle.step_time_mode = 0
feed = sim.add_step('Feed', time=6000.0)
feed.bottom.set_streams('inlet', [
    sk.Stream('CO2 Inlet', flow=sk.volumetric_flow(8.333333333333335e-07), y={'Helium': 0.3, 'Nitrogen': 0.0, 'CarbonDioxide': 0.7}, temperature=295.0),
])
feed.top.set_pressure('outlet', 97000.0, y={'CarbonDioxide': 0.0, 'Nitrogen': 0.0, 'Helium': 1.0}, temperature=293.0)

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 0.0
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 0
sim.css.min_cycles = 5
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
